"    async function saveTimestampsToBackend() {
      if (!activeTrack) return;
      try {
        const res = await fetch(`/api/songs/${activeTrack.id}/timestamps`, {
          method: 'POST',
          headers: { 'Content-Type': 'application/json' },
          body: JSON.stringify({ lines: activeTrack.lines })
        });
        if (res.ok) {
          alert('Timestamps saved successfully to In-Memory Store and data.jsonl!');
        } else {
          alert('Failed to save timestamps.');
        }
      } catch (err) {
        alert('Error saving timestamps: ' + err.message);
      }
    }

    async function promptChangeYouTubeVideo() {
      if (!activeTrack) return;
      const currentUrl = activeTrack.youtubeVideoId ? `https://www.youtube.com/watch?v=${activeTrack.youtubeVideoId}` : '';
      const newUrl = prompt(`Enter new YouTube Link or Video ID for "${activeTrack.title}":`, currentUrl);
      if (!newUrl || newUrl.trim() === '') return;

      try {
        const res = await fetch(`/api/songs/${activeTrack.id}/youtube`, {
          method: 'POST',
          headers: { 'Content-Type': 'application/json' },
          body: JSON.stringify({ videoId: newUrl.trim() })
        });
        const data = await res.json();
        if (res.ok && data.song) {
          activeTrack.youtubeVideoId = data.song.youtubeVideoId;
          document.getElementById('metaYoutube').textContent = activeTrack.youtubeVideoId;
          loadVideo(activeTrack.youtubeVideoId);
          alert('YouTube backing track updated and saved!');
        } else {
          alert('Error updating YouTube video: ' + (data.error || 'Failed'));
        }
      } catch (err) {
        alert('Request failed: ' + err.message);
      }
    }
  </script>
</body>
</html>"

