"    function recordTapWord() {
      if (!tapMode || !activeTrack || !ytPlayer) return;
      const now = ytPlayer.getCurrentTime() || 0;

      if (tapCurrentWordIdx < flatWordList.length) {
        const item = flatWordList[tapCurrentWordIdx];
        const line = activeTrack.lines[item.lineIndex];
        const word = line.words[item.wordIndex];

        const newStart = parseFloat(now.toFixed(2));
        const timeDelta = newStart - word.start;

        word.start = newStart;
        word.end = parseFloat((now + 0.6).toFixed(2)); // Default duration 600ms or until next tap

        if (tapCurrentWordIdx > 0) {
          // Adjust previous word's end time to current start
          const prevItem = flatWordList[tapCurrentWordIdx - 1];
          const prevWord = activeTrack.lines[prevItem.lineIndex].words[prevItem.wordIndex];
          prevWord.end = word.start;
        }

        // Shift all future words by the delta so they don't overlap!
        for (let i = tapCurrentWordIdx + 1; i < flatWordList.length; i++) {
          const fItem = flatWordList[i];
          const fWord = activeTrack.lines[fItem.lineIndex].words[fItem.wordIndex];
          fWord.start = parseFloat((fWord.start + timeDelta).toFixed(2));
          fWord.end = parseFloat((fWord.end + timeDelta).toFixed(2));
        }

        tapCurrentWordIdx++;

        if (tapCurrentWordIdx >= flatWordList.length) {
          saveTimestampsToBackend();
          alert("Finished tapping song! Timestamps auto-saved.");
        }
      }
    }"

